function hasValidCustomSource() {
    const value = (source.getLoginInfoMap())['自定义源站'];
    return !(value == null || value == undefined || value == "" || String(value).trim() == "");
}

function showCustomSourceAlert() {
    const customSource = (source.getLoginInfoMap())['自定义源站'];
    java.toast(
        "\n⚠️ 自定义源站配置提醒 ⚠️\n" +
        "──────────────────\n" +
        "检测到已设置自定义源站: \n✨" +
        "【" + (customSource || "") + "】✨\n" +
        "──────────────────\n" +
        "请前往「书源登录」清除配置\n" +
        "才能使指定源站切换生效"
    );
}

function updateConfig(key, value, message, gender) {
    if (key == "source" && hasValidCustomSource()) {
        showCustomSourceAlert();
        return;
    }

    try {
        var config = JSON.parse(source.getVariable());
        if (!config || !Array.isArray(config) || config.length === 0) {
            config = [{}];
        }
        config[0][key] = value;
        if (gender !== undefined) {
            config[0]["gender"] = gender;
        }
        source.setVariable(JSON.stringify(config));
        java.toast(message || "设置已更新");
    } catch(e) {
        var newConfig = {[key]: value};
        if (gender !== undefined) {
            newConfig["gender"] = gender;
        }
        source.setVariable(JSON.stringify([newConfig]));
        java.toast(message || "初始化设置");
    }
}

function get_cx() {
    try {
        var configStr = source.getVariable();
        if (!configStr || configStr.trim() == "") {
            configStr = JSON.stringify([{host: hosts[0]}]);
            source.setVariable(configStr);
        }
        var config = JSON.parse(configStr);
        if (!config || !Array.isArray(config) || config.length == 0) {
            config = [{host: hosts[0]}]; 
            source.setVariable(JSON.stringify(config)); 
        }
        var currentHost = getServerHost();
        var currentSource = (!('source' in config[0]) || !config[0].source) ? "☁️ 聚合搜索 ☁️" : (sourceList.find(item => item.v === config[0].source)?.m || config[0].source);
        var currentGender = config[0].gender === "boy" ? " 男🧸频 " : (config[0].gender === "girl" ? " 女🎀频 " : " 未设置 ");
        var currentTone = config[0].sz ? "音色" + data[parseInt(config[0].sz) || 1][0] : "默认音色";
        var customSource = (source.getLoginInfoMap())['自定义源站'] || "未设置"; 
        var customSourceStatus = hasValidCustomSource() ? "🔗 " + customSource : "当前未设置，示例：米读,书旗";
        var keyStatus = (source.getLoginInfoMap())['密钥'] ? "✅ 已填写" : "❌ 未填写";
        var username = "未登录";

        try {
            var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) || (source.getLoginInfoMap())['手动登录Token'];
            if (cookie_) username = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
                method: "GET", headers: { "Cookie": "sessionid=" + cookie_ }
            }))).data?.name || "已登录(未获取到用户名)";
        } catch (e) {}

        java.longToast(
            "\n───────────────\n" +
            "☑️  配  置  状  态 ☑️\n" +
            "───────────────\n" +
            "🔘 服  务  器 🔘\n" + currentHost + "\n" +
            "───────────────\n" +
            "🌋 书  源 🌋\n" + currentSource + "\n" +
            "───────────────\n" +
            "🏔️ 偏  好 🏔️\n" + currentGender + "\n" +
            "───────────────\n" +
            "🎧 AI 音 色 🎧\n" + currentTone + "\n" +
            "───────────────\n" +
            "❇️ 自 定 义 源 ❇️\n" + customSourceStatus + "\n" +
            "───────────────\n" +
            "🔆 密 匙 状 态 🔆\n" + keyStatus + "\n" +
            "───────────────\n" +
            "🍅 登 录 用 户 🍅\n" + username + "\n" +
            "───────────────\n" +
            "\n✨ 提示：点击按钮切换配置"
        );
    } catch(e) {
        source.setVariable(JSON.stringify([{host: hosts[0]}]));
        java.toast("⚠️ 配置初始化完成，请重试");
    }
}

this.sethost = function() {
    try {
        var config = JSON.parse(source.getVariable());
        if (!config || !Array.isArray(config) || config.length == 0) {
            config = [{host: hosts[0]}];
        }

        var currentHost = config[0].host || hosts[0];
        var currentIndex = hosts.indexOf(currentHost);
        var newIndex = (currentIndex + 1) % hosts.length;
        var newHost = hosts[newIndex];
        config[0].host = newHost;
        source.setVariable(JSON.stringify(config));
        java.toast("\n切换到：\n" + newHost + "");
    } catch(e) {
        source.setVariable(JSON.stringify([{host: hosts[0]}]));
        java.toast("【n】已初始化：" + hosts[0]);
    }
};

for (var i = 0; i < sourceList.length; i++) {
    (function() {
        var s = sourceList[i];
        this[s.n] = function() {
            if (hasValidCustomSource()) {
                showCustomSourceAlert();
                return;
            } if (s.g) {
                updateConfig("source", s.v, "\n已切换" + (s.v ? '到❇️' : '') + s.m +"❇️\n刷新发现页生效", s.g);
            } else {
                updateConfig("source", s.v, "\n已切换" + (s.v ? '到❇️' : '') + s.m +"❇️\n刷新发现页生效");
            }
        };
    }).call(this);
}

function Map(e) {
    if (e == "source" && hasValidCustomSource()) {
        showCustomSourceAlert();
        return (source.getLoginInfoMap())['自定义源站'];
    }
    var infomap = source.getLoginInfoMap();
    const value = infomap[e];
    if (!value) {
        java.longToast("需要填写密钥");
    }
    return value;
}

function login_(openBrowser, checkMode) {
    var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) || 
                 (source.getLoginInfoMap())['手动登录Token'];

    if (cookie_ && cookie_ != "" && !checkMode) {
        java.toast(source.variableComment ? "请手动移除token后再次登录" : "请不要重复登录，请先退出登录！");
        return false;
    }

    if (openBrowser) {
        try { 	java.startBrowserAwait("https://fanqienovel.com/", "登录");
        } catch (e) {
            java.toast(e);
        }
    }

    cookie.removeCookie("snssdk.com");
    cookie_ = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) || 
    (source.getLoginInfoMap())['手动登录Token']);

    let user;
    try {
        user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
            method: "GET",
            headers: { "Cookie": cookie_ }
        }))).data.name;
    } catch (e) { java.log(e); }

    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败");
        return false;
    }

    java.toast("欢迎 " + user + "\n登录成功！");
    return true;
}

function l2(a, b) {
    try {
        login_(a, b);
    } catch (e) {
        java.log(e+"\n"+e.stack);
    }
}

function login(){}

function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    if (String(cookie.getKey("fanqienovel.com", "sessionid")) || 
        (source.getLoginInfoMap())['手动登录Token']) {
        java.toast("请手动移除填写的Token");
    } else {
        java.toast("退出登录成功");
    }
}

